25	const apiMaxResponseBytes = 32 << 20 // 32 MiB cap on a printed response body.
26	
27	type apiFlags struct {
28		to           string
29		method       string
30		rawFields    []string
31		typedFields  []string
32		headers      []string
33		input        string
34		include      bool
35		insecureHTTP bool
36	}
