38	func newAPICmd() *cobra.Command {
39		f := &apiFlags{}
40		cmd := &cobra.Command{
41			Use:   "api <path>",
42			Short: "Make an authenticated request to an Entire API and print the response",
43			Long: "Make an authenticated HTTP request to an Entire API and print the JSON response.\n\n" +
44				"The CLI attaches the right bearer token and dials the right host for the\n" +
45				"chosen backend, so you don't have to plumb auth yourself:\n\n" +
46				"  --to core   the control plane (default): orgs, repos, mirrors, clusters, /me\n" +
47				"  --to cell   your home entire-api cell: /me/* activity, repo aggregates\n\n" +
48				"<path> is the full path on that host, e.g. /api/v1/clusters. These\n" +
49				"placeholders are filled from the current repo's origin remote:\n" +
50				"  {owner} {repo}   the GitHub owner / repo\n" +
51				"  {repo_id}        the repo's Entire ULID (from its mirror) — cells key on this\n\n" +
52				"The method is GET unless a field/body is given (then POST); override with -X.",
53			Example: "  entire api /api/v1/clusters\n" +
54				"  entire api --to cell /api/v1/me/activity\n" +
55				"  entire api --to cell \"/api/v1/me/recap?repo={repo_id}\"\n" +
56				"  entire api -X POST /api/v1/projects -f name=demo",
57			Args: cobra.ExactArgs(1),
58			RunE: func(cmd *cobra.Command, args []string) error {
59				return runAPI(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), args[0], f)
60			},
61		}
62		cmd.Flags().StringVar(&f.to, "to", "core", "which backend to call: core or cell")
63		cmd.Flags().StringVarP(&f.method, "method", "X", "", "HTTP method (default GET, or POST when a field/body is given)")
64		cmd.Flags().StringArrayVarP(&f.rawFields, "raw-field", "f", nil, "add a string parameter in key=value format (repeatable)")
65		cmd.Flags().StringArrayVarP(&f.typedFields, "field", "F", nil, "add a typed parameter in key=value format; true/false/null/numbers are converted (repeatable)")
66		cmd.Flags().StringArrayVarP(&f.headers, "header", "H", nil, "add a request header in key:value format (repeatable)")
67		cmd.Flags().StringVar(&f.input, "input", "", "file with the request body (\"-\" for stdin)")
68		cmd.Flags().BoolVarP(&f.include, "include", "i", false, "print the response status line and headers too")
69		addInsecureHTTPAuthFlag(cmd, &f.insecureHTTP)
70		return cmd
71	}
