113	// resolveAPIClient builds an authenticated client for the chosen backend. Both
114	// return an *api.Client whose base URL is the backend origin, so <path> is the
115	// full path (e.g. /api/v1/…) against that host.
116	func resolveAPIClient(ctx context.Context, to string, insecure bool) (*api.Client, error) {
117		switch strings.ToLower(strings.TrimSpace(to)) {
118		case "", "core":
119			target, err := resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
120			if err != nil {
121				return nil, err
122			}
123			if target.token == "" {
124				// Return a normal (non-silent) error so main.go prints the hint;
125				// a SilentError would exit non-zero with no explanation.
126				return nil, errors.New("not logged in: run 'entire login' to authenticate")
127			}
128			if !insecure && target.coreURL != "" {
129				if err := api.RequireSecureURL(target.coreURL); err != nil {
130					return nil, fmt.Errorf("control-plane URL check: %w", err)
131				}
132			}
133			return api.NewClientWithBaseURL(target.token, target.coreURL), nil
134		case "cell":
135			client, err := auth.NewEntireAPICellClient(ctx, insecure, nil)
136			if err != nil {
137				return nil, err //nolint:wrapcheck // NewEntireAPICellClient already returns contextual auth errors
138			}
139			return client, nil
140		default:
141			return nil, fmt.Errorf("unknown --to %q (use core or cell)", to)
142		}
143	}
144	
145	// validateAPIPath rejects anything that isn't origin-relative. The path is
146	// resolved against the backend origin via url.ResolveReference, which lets an
147	// absolute ("https://evil/…") or scheme-relative ("//evil/…") value replace the
148	// host — and the bearer transport would then send the Entire token there. So a
149	// path carrying its own scheme or host is refused before any request is made.
150	func validateAPIPath(path string) error {
151		u, err := url.Parse(path)
152		if err != nil {
153			return fmt.Errorf("invalid path %q: %w", path, err)
154		}
155		if u.Scheme != "" || u.Host != "" {
156			return fmt.Errorf("path must be origin-relative (e.g. /api/v1/…), not a cross-host or absolute URL: %q", path)
157		}
158		return nil
159	}
160	
161	// expandAPIPlaceholders fills {owner}/{repo}/{repo_id} from the current repo.
162	// Resolution is lazy: {owner}/{repo} need only the git remote; {repo_id} costs
163	// a control-plane mirror lookup, so it's only done when actually referenced.
164	func expandAPIPlaceholders(ctx context.Context, s string) (string, error) {
165		needOwnerRepo := strings.Contains(s, "{owner}") || strings.Contains(s, "{repo}")
166		needRepoID := strings.Contains(s, "{repo_id}")
167		if !needOwnerRepo && !needRepoID {
168			return s, nil
169		}
170	
171		// Resolve the origin remote once, even when both {owner}/{repo} and
172		// {repo_id} are present, and thread it into the mirror lookup.
173		forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
174		if err != nil {
175			return "", fmt.Errorf("resolve current repo from origin remote: %w", err)
176		}
177		if needOwnerRepo {
178			s = strings.ReplaceAll(s, "{owner}", owner)
179			s = strings.ReplaceAll(s, "{repo}", repo)
180		}
181		if needRepoID {
182			id, err := resolveCurrentRepoID(ctx, forge, owner, repo)
183			if err != nil {
184				return "", err
185			}
186			s = strings.ReplaceAll(s, "{repo_id}", id)
187		}
188		return s, nil
189	}
190	
191	// resolveCurrentRepoID resolves a repo's Entire ULID from its mirror (the mirror
192	// id, which entire-api uses as the repo_id), given its already-resolved origin
193	// coordinates. Picks the first active placement.
194	func resolveCurrentRepoID(ctx context.Context, forge, owner, repo string) (string, error) {
195		if f := strings.ToLower(strings.TrimSpace(forge)); f != "gh" && f != mirrorCloneProviderGitHub {
196			return "", fmt.Errorf("{repo_id} needs a GitHub repo; origin forge is %q", forge)
197		}
198		c, err := coreapi.New()
199		if err != nil {
200			return "", fmt.Errorf("resolve {repo_id} needs the control plane: %w", err)
201		}
202		mirrors, err := listMirrorsForRepo(ctx, c, mirrorCloneProviderGitHub, strings.ToLower(owner), strings.ToLower(repo))
203		if err != nil {
204			return "", fmt.Errorf("list mirrors for %s/%s: %w", owner, repo, err)
205		}
206		for i := range mirrors {
207			if !isActiveMirror(mirrors[i]) {
208				continue
209			}
210			if id := strings.TrimSpace(mirrors[i].MirrorId); id != "" {
211				return id, nil
212			}
213		}
214		return "", fmt.Errorf("no active mirror for %s/%s to resolve {repo_id}", owner, repo)
215	}
