217	// buildAPIFields merges -f (always string) and -F (type-inferred) into one map.
218	// Returns an empty (non-nil) map when no fields are given.
219	func buildAPIFields(rawFields, typedFields []string) (map[string]any, error) {
220		out := make(map[string]any, len(rawFields)+len(typedFields))
221		for _, kv := range rawFields {
222			k, v, ok := strings.Cut(kv, "=")
223			if !ok || k == "" {
224				return nil, fmt.Errorf("invalid -f %q (want key=value)", kv)
225			}
226			out[k] = v
227		}
228		for _, kv := range typedFields {
229			k, v, ok := strings.Cut(kv, "=")
230			if !ok || k == "" {
231				return nil, fmt.Errorf("invalid -F %q (want key=value)", kv)
232			}
233			out[k] = inferFieldValue(v)
234		}
235		return out, nil
236	}
237	
238	// inferFieldValue mirrors gh's -F conversion: true/false/null and numbers get
239	// their JSON type; everything else stays a string.
240	func inferFieldValue(v string) any {
241		switch v {
242		case "true":
243			return true
244		case "false":
245			return false
246		case "null":
247			return nil
248		}
249		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
250			return n
251		}
252		if fl, err := strconv.ParseFloat(v, 64); err == nil {
253			return fl
254		}
255		return v
256	}
