258	type apiRequest struct {
259		method string
260		path   string
261		body   io.Reader
262	}
263	
264	// buildAPIRequestBody resolves method + body from the flags: --input wins (raw
265	// body), else fields become a JSON body. The method defaults to GET, or POST
266	// when there's a body; an explicit -X wins. For a GET with fields, the fields
267	// go on the query string instead of a body.
268	func buildAPIRequestBody(path string, f *apiFlags, fields map[string]any) (apiRequest, error) {
269		method := strings.ToUpper(strings.TrimSpace(f.method))
270		if method == "" {
271			if f.input != "" || len(fields) > 0 {
272				method = http.MethodPost
273			} else {
274				method = http.MethodGet
275			}
276		}
277	
278		if f.input != "" {
279			if len(fields) > 0 {
280				return apiRequest{}, errors.New("use either --input or -f/-F, not both")
281			}
282			raw, err := readAPIInput(f.input)
283			if err != nil {
284				return apiRequest{}, err
285			}
286			return apiRequest{method: method, path: path, body: bytes.NewReader(raw)}, nil
287		}
288	
289		if len(fields) == 0 {
290			return apiRequest{method: method, path: path, body: nil}, nil
291		}
292	
293		if method == http.MethodGet {
294			q, err := fieldsToQuery(fields)
295			if err != nil {
296				return apiRequest{}, err
297			}
298			return apiRequest{method: method, path: appendQuery(path, q), body: nil}, nil
299		}
300	
301		data, err := json.Marshal(fields)
302		if err != nil {
303			return apiRequest{}, fmt.Errorf("encode fields: %w", err)
304		}
305		return apiRequest{method: method, path: path, body: bytes.NewReader(data)}, nil
306	}
307	
308	// fieldsToQuery stringifies fields for a GET query string. Non-string scalars
309	// are rendered with their JSON form (e.g. true, 42) so -F round-trips sensibly.
310	func fieldsToQuery(fields map[string]any) (url.Values, error) {
311		q := make(url.Values, len(fields))
312		for k, v := range fields {
313			switch val := v.(type) {
314			case string:
315				q.Set(k, val)
316			case nil:
317				q.Set(k, "null")
318			default:
319				b, err := json.Marshal(val)
320				if err != nil {
321					return nil, fmt.Errorf("encode field %q: %w", k, err)
322				}
323				q.Set(k, string(b))
324			}
325		}
326		return q, nil
327	}
328	
329	// appendQuery adds encoded query params to a path that may already have some.
330	func appendQuery(path string, q url.Values) string {
331		if len(q) == 0 {
332			return path
333		}
334		sep := "?"
335		if strings.Contains(path, "?") {
336			sep = "&"
337		}
338		return path + sep + q.Encode()
339	}
340	
341	// readWithinLimit reads r up to limit bytes and errors if the source is larger,
342	// rather than silently truncating — a truncated JSON body would be malformed
343	// and misleading for an escape-hatch command.
344	func readWithinLimit(r io.Reader, limit int64) ([]byte, error) {
345		raw, err := io.ReadAll(io.LimitReader(r, limit+1))
346		if err != nil {
347			return nil, fmt.Errorf("read: %w", err)
348		}
349		if int64(len(raw)) > limit {
350			return nil, fmt.Errorf("exceeds the %d-byte limit", limit)
351		}
352		return raw, nil
353	}
354	
355	func readAPIInput(path string) ([]byte, error) {
356		if path == "-" {
357			raw, err := readWithinLimit(os.Stdin, apiMaxResponseBytes)
358			if err != nil {
359				return nil, fmt.Errorf("read body from stdin: %w", err)
360			}
361			return raw, nil
362		}
363		raw, err := os.ReadFile(path) //nolint:gosec // a user-specified request-body file is the whole point
364		if err != nil {
365			return nil, fmt.Errorf("read body file: %w", err)
366		}
367		return raw, nil
368	}
369	
370	func parseAPIHeaders(headers []string) (http.Header, error) {
371		h := make(http.Header, len(headers))
372		for _, kv := range headers {
373			k, v, ok := strings.Cut(kv, ":")
374			if !ok || strings.TrimSpace(k) == "" {
375				return nil, fmt.Errorf("invalid -H %q (want key:value)", kv)
376			}
377			h.Add(strings.TrimSpace(k), strings.TrimSpace(v))
378		}
379		return h, nil
380	}
381	
382	func writeAPIResponse(w, errW io.Writer, resp *http.Response, include bool) error {
383		if include {
384			fmt.Fprintf(errW, "%s %s\n", resp.Proto, resp.Status)
385			names := make([]string, 0, len(resp.Header))
386			for name := range resp.Header {
387				names = append(names, name)
388			}
389			sort.Strings(names)
390			for _, name := range names {
391				for _, v := range resp.Header[name] {
392					fmt.Fprintf(errW, "%s: %s\n", name, v)
393				}
394			}
395			fmt.Fprintln(errW)
396		}
397	
398		raw, err := readWithinLimit(resp.Body, apiMaxResponseBytes)
399		if err != nil {
400			return fmt.Errorf("read response body: %w", err)
401		}
402	
403		toWrite := raw
404		if body := bytes.TrimSpace(raw); len(body) > 0 && json.Valid(body) {
405			var pretty bytes.Buffer
406			if json.Indent(&pretty, body, "", "  ") == nil {
407				pretty.WriteByte('\n')
408				toWrite = pretty.Bytes()
409			}
410		}
411		if _, err := w.Write(toWrite); err != nil {
412			return fmt.Errorf("write response: %w", err)
413		}
414	
415		// Non-2xx: the body is already printed; return a silent error so the exit
416		// code is non-zero for scripts without reprinting anything.
417		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
418			return NewSilentError(fmt.Errorf("HTTP %d", resp.StatusCode))
419		}
420		return nil
421	}
