1	package auth
2	
3	import (
4		"context"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"os"
13		"regexp"
14		"strings"
15		"time"
16	
17		"github.com/entireio/cli/cmd/entire/cli/api"
18		"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
19		"github.com/entireio/cli/internal/entireclient/httputil"
20		"github.com/entireio/cli/internal/entireclient/userdirs"
21	)
22	
23	const (
24		cellDataAPITimeout = 30 * time.Second
25	
26		// JurisdictionIdentityScope is the scope jurisdiction identity tokens
27		// are minted with (also used by git-remote-entire's jurisdiction git
28		// auth). The receiving surface authorizes live per request, so the
29		// scope carries identity semantics only, not a permission grant.
30		JurisdictionIdentityScope = "openid"
31	
32		// clustersAPIPath is entire-core's cluster catalog endpoint.
33		clustersAPIPath = "/api/v1/clusters"
34	)
35	
36	// jurisdictionLabelPattern bounds a home_jurisdiction claim to a single DNS
37	// label before it is substituted into a URL template. The claim rides on the
38	// login JWT (which we decode without verifying the signature) and, for the
39	// home-jurisdiction fallback path, is attacker-influenceable if a token is ever
40	// mis-minted; constraining it to [a-z0-9-] means it can only ever name a
41	// sibling jurisdiction, never inject host/scheme syntax (e.g.
42	// "us.auth.evil.tld") into jurisdictionAudience / jurisdictionCoreURL.
43	var jurisdictionLabelPattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$`)
44	
45	// CellTarget pins the entire-api cell a repo-scoped call must reach and the
46	// jurisdiction its identity token must be minted for. The cli layer resolves it
47	// from the repo's own cluster (via coreapi mirrors/clusters), so a repo-scoped
48	// route reaches the cell that HOSTS the repo — not the caller's home cell. A nil
49	// target falls back to home-jurisdiction routing (derived from the login JWT),
50	// which is correct for the common same-region case and for local dev.
51	type CellTarget struct {
52		// BaseURL is the cell's apiUrl to dial (e.g. https://aws-eu-west-1.api.entire.io).
53		BaseURL string
54		// Jurisdiction is the repo's cluster jurisdiction; it drives the identity
55		// token's audience and the core the exchange is performed at.
56		Jurisdiction string
57	}
58	
59	// resolveContextForCellAPI is the discovery seam for cell routing, swapped in
60	// tests. Mirrors resolveContextForAPI.
61	var resolveContextForCellAPI resolveContextFunc = clusterdiscovery.ResolveContextForAPI
62	
63	// SetResolveContextForCellAPIForTest overrides the cell-API discovery seam.
64	func SetResolveContextForCellAPIForTest(t interface{ Helper() }, fn resolveContextFunc) func() {
65		t.Helper()
66		prev := resolveContextForCellAPI
67		resolveContextForCellAPI = fn
68		return func() { resolveContextForCellAPI = prev }
69	}
70	
71	// cellExchangeTransportForTest, when non-nil, is the HTTP transport used for
72	// jurisdiction token exchange and cluster listing. Production leaves it nil.
73	var cellExchangeTransportForTest http.RoundTripper
74	
75	// SetCellExchangeTransportForTest overrides the transport used for jurisdiction
76	// token exchange and cluster listing, returning a restore closure — the same
77	// set/restore convention the rest of the package uses for test seams.
78	func SetCellExchangeTransportForTest(t interface{ Helper() }, rt http.RoundTripper) func() {
79		t.Helper()
80		prev := cellExchangeTransportForTest
81		cellExchangeTransportForTest = rt
82		return func() { cellExchangeTransportForTest = prev }
83	}
84	
85	// NewEntireAPICellClient returns an authenticated client aimed at an entire-api
86	// cell, carrying a jurisdictional identity token (scope=openid, aud=jurisdiction
87	// host). Repo-scoped entire-api routes do not accept the narrowed api-access
88	// bearer minted for the BFF origin — they require a cell identity token
89	// (COR-666).
90	//
91	// Cell selection, in precedence order:
92	//   - target != nil: dial target.BaseURL and mint for target.Jurisdiction. This
93	//     is the repo-scoped path — the caller (cli) resolved the repo's own cell.
94	//   - the configured data host already targets a cell (host contains ".api."):
95	//     keep that origin.
96	//   - a loopback data host (local dev): keep that origin.
97	//   - otherwise the data host is a BFF/apex: resolve the caller's home-cell
98	//     apiUrl from the cluster catalog (home-jurisdiction fallback).
99	func NewEntireAPICellClient(ctx context.Context, insecureHTTP bool, target *CellTarget) (*api.Client, error) {
100		dataURL := api.BaseURL()
101		if insecureHTTP {
102			EnableInsecureHTTP()
103		} else if err := api.RequireSecureURL(dataURL); err != nil {
104			return nil, fmt.Errorf("base URL check: %w", err)
105		}
106	
107		dataOrigin := api.OriginOnly(dataURL)
108		host, ok := hostOf(dataOrigin)
109		if !ok {
110			return nil, fmt.Errorf("data API URL %q has no host to discover against", dataURL)
111		}
112	
113		dctx, cancel := context.WithTimeout(ctx, dataAPIDiscoveryTimeout)
114		defer cancel()
115		var httpClient *http.Client
116		switch {
117		case cellExchangeTransportForTest != nil:
118			httpClient = &http.Client{Timeout: cellDataAPITimeout, Transport: cellExchangeTransportForTest}
119		case shouldUsePlainHTTPDiscovery(dataOrigin):
120			httpClient = dataAPIDiscoveryClient(dataOrigin)
121			httpClient.Timeout = cellDataAPITimeout
122		default:
123			httpClient = &http.Client{Timeout: cellDataAPITimeout}
124		}
125	
126		selected, err := resolveContextForCellAPI(dctx, userdirs.Config(), userdirs.Cache(), host, httpClient, nil)
127		if errors.Is(err, clusterdiscovery.ErrDiscoveryUnavailable) {
128			return nil, fmt.Errorf("%s does not advertise its trusted login servers (/.well-known/entire-api.json missing or unreachable); cannot authenticate: %w", host, err)
129		}
130		if err != nil {
131			return nil, err
132		}
133	
134		// Gate the login provider's HTTPS relaxation on the core it actually dials
135		// (selected.CoreURL) plus the explicit --insecure-http-auth opt-in, matching
136		// the sibling ResolveDataAPIToken. A loopback data API must not relax HTTPS
137		// for a non-loopback core.
138		allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(selected.CoreURL)
139		loginProvider, err := NewRefreshingLoginProvider(selected, cellExchangeTransportForTest, allowInsecure)
140		if err != nil {
141			return nil, err
142		}
143	
144		loginJWT, err := loginProvider(ctx)
145		if err != nil {
146			if errors.Is(err, ErrNotLoggedIn) {
147				return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
148			}
149			// The provider already prefixes "refresh login token:"; return as-is to
150			// avoid a doubled prefix.
151			return nil, err
