181	// targetJurisdiction picks the jurisdiction to mint for: the explicit repo
182	// target when present, otherwise the caller's home jurisdiction from the login
183	// JWT. The result is validated as a DNS label before it is templated into URLs.
184	func targetJurisdiction(target *CellTarget, loginJWT string) (string, error) {
185		jurisdiction := ""
186		if target != nil {
187			jurisdiction = strings.TrimSpace(target.Jurisdiction)
188		}
189		if jurisdiction == "" {
190			var err error
191			jurisdiction, err = HomeJurisdictionFromLoginJWT(loginJWT)
192			if err != nil {
193				return "", err
194			}
195		}
196		if jurisdiction == "" {
197			return "", errors.New("login token has no home_jurisdiction claim; cannot route to entire-api cell")
198		}
199		if !jurisdictionLabelPattern.MatchString(jurisdiction) {
200			return "", fmt.Errorf("jurisdiction %q is not a valid label; refusing to route", jurisdiction)
201		}
202		return jurisdiction, nil
203	}
