205	// resolveTargetCellBaseURL decides which cell origin to dial. See
206	// NewEntireAPICellClient's precedence doc.
207	func resolveTargetCellBaseURL(ctx context.Context, target *CellTarget, dataOrigin, jurisdiction, coreURL, loginJWT string, httpClient *http.Client) (string, error) {
208		if target != nil && strings.TrimSpace(target.BaseURL) != "" {
209			return strings.TrimRight(target.BaseURL, "/"), nil
210		}
211		if !isBFFOrigin(dataOrigin) {
212			// Already a cell URL, or a loopback local-dev host: keep it verbatim.
213			return strings.TrimRight(dataOrigin, "/"), nil
214		}
215		return resolveCellAPIBaseURL(ctx, coreURL, loginJWT, jurisdiction, httpClient)
216	}
