218	// isBFFOrigin reports whether origin is a BFF / apex host that fronts multiple
219	// cells (so the actual cell must be resolved from the cluster catalog), as
220	// opposed to a direct entire-api cell (host contains ".api.") or a loopback
221	// local-dev host (kept verbatim). This is environment-agnostic: it recognises
222	// prod (entire.io), staging (partial.to) and any future apex without a
223	// hardcoded domain list.
224	func isBFFOrigin(origin string) bool {
225		u, err := url.Parse(origin)
226		if err != nil || u.Host == "" {
227			return false
228		}
229		host := strings.ToLower(u.Hostname())
230		if host == "" || isLoopbackHost(host) {
231			return false
232		}
233		// A direct cell advertises itself under an ".api." label; anything else that
234		// isn't loopback is treated as a BFF/apex needing cell resolution.
235		return !strings.Contains(host, ".api.")
236	}
