266	// environmentFamily picks the registrable apex to template jurisdiction URLs
267	// against. The configured data host (what the user pointed the CLI at) is the
268	// most reliable signal for prod-vs-staging, so it wins; the discovered login
269	// core is the fallback.
270	func environmentFamily(dataOrigin, discoveredCore string) string {
271		if fam := entireDomainFamily(dataOrigin); fam != "" {
272			return fam
273		}
274		return entireDomainFamily(discoveredCore)
275	}
