277	// jurisdictionAudience returns the aud the entire-api cell for `jurisdiction`
278	// pins its identity tokens to (its jurisdiction host). Precedence:
279	//   - ENTIRE_API_AUDIENCE_TEMPLATE (with {jurisdiction}) if set;
280	//   - else https://{jurisdiction}.<family> for the environment family;
281	//   - else (loopback/custom) the data origin, best-effort and overridable.
282	//
283	// This mirrors the BFF's buildAudience(template, jurisdiction) (repos-stream.ts).
284	func jurisdictionAudience(jurisdiction, dataOrigin, discoveredCore string) string {
285		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_API_AUDIENCE_TEMPLATE")); tmpl != "" {
286			return applyJurisdictionTemplate(tmpl, jurisdiction)
287		}
288		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
289			return "https://" + jurisdiction + "." + fam
290		}
291		return strings.TrimRight(dataOrigin, "/")
292	}
293	
294	// jurisdictionCoreURL returns the entire-core origin the identity-token exchange
295	// is performed at for `jurisdiction`. Precedence:
296	//   - a loopback discovered core (local dev): honour it verbatim — the local
297	//     core signs the local login JWT, and the prod template would send the
298	//     exchange to production, which rejects the local token;
299	//   - ENTIRE_CORE_BASE_URL_TEMPLATE (with {jurisdiction}) if set;
300	//   - else https://{jurisdiction}.auth.<family> for the environment family;
301	//   - else the discovered core verbatim.
302	//
303	// This mirrors the BFF's buildCoreBaseUrl(template, jurisdiction, fallback),
304	// which honours a fallback core when the template can't produce one.
305	func jurisdictionCoreURL(jurisdiction, dataOrigin, discoveredCore string) string {
306		if isLoopbackHTTP(discoveredCore) {
307			return strings.TrimRight(discoveredCore, "/")
308		}
309		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_CORE_BASE_URL_TEMPLATE")); tmpl != "" {
310			// Apply unconditionally: applyJurisdictionTemplate is a no-op when the
311			// template has no {jurisdiction}, yielding the fixed core verbatim — the
312			// single-core case, matching the BFF's buildCoreBaseUrl and this file's
313			// own audience handling.
314			return applyJurisdictionTemplate(tmpl, jurisdiction)
315		}
316		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
317			return "https://" + jurisdiction + ".auth." + fam
318		}
319		return strings.TrimRight(discoveredCore, "/")
320	}
