326	// requireSafeExchangeURL rejects a target the login JWT / identity token would
327	// be sent to unless it is https (or an explicitly-allowed loopback/insecure
328	// http). It affirmatively requires the https scheme — not merely "not http" —
329	// so ftp/ws/scheme-relative/empty targets from a buggy core catalog can't
330	// smuggle the login JWT off https. Mirrors the tokenmanager guard the sibling
331	// data_api.go relies on.
332	func requireSafeExchangeURL(label, raw string) error {
333		if insecureHTTPEnabled() || isLoopbackHTTP(raw) {
334			return nil
335		}
336		u, err := url.Parse(raw)
337		if err != nil {
338			return fmt.Errorf("%s URL check: parse %q: %w", label, raw, err)
339		}
340		if u.Scheme != "https" || u.Host == "" {
341			return fmt.Errorf("%s URL %q must be https", label, raw)
342		}
343		return nil
344	}
