346	// HomeJurisdictionFromLoginJWT reads the home_jurisdiction claim without
347	// verifying the signature — callers only route with it; the server
348	// re-verifies. Returns "" (no error) when the claim is absent so each
349	// caller can phrase its own missing-claim error. Shared with
350	// git-remote-entire's jurisdiction git auth.
351	func HomeJurisdictionFromLoginJWT(loginJWT string) (string, error) {
352		parts := strings.Split(loginJWT, ".")
353		if len(parts) < 2 {
354			return "", errors.New("login token is not a JWT")
355		}
356		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
357		if err != nil {
358			return "", fmt.Errorf("decode login token payload: %w", err)
359		}
360		var claims struct {
361			HomeJurisdiction string `json:"home_jurisdiction"`
362		}
363		if err := json.Unmarshal(payload, &claims); err != nil {
364			return "", fmt.Errorf("parse login token payload: %w", err)
365		}
366		return claims.HomeJurisdiction, nil
367	}
