375	// resolveCellAPIBaseURL is the home-jurisdiction fallback cell resolver: it
376	// lists the caller's clusters and picks the apiUrl for `jurisdiction` (default
377	// cluster first). It hand-parses GET /api/v1/clusters rather than reusing the
378	// generated coreapi.ListClusters() because coreapi imports this (auth) package,
379	// so auth cannot import coreapi without a cycle — the repo-scoped path avoids
380	// this by resolving the cell in the cli layer (see resolveExpertsCellTarget).
381	func resolveCellAPIBaseURL(ctx context.Context, coreURL, loginJWT, jurisdiction string, httpClient *http.Client) (string, error) {
382		req, err := http.NewRequestWithContext(ctx, http.MethodGet, strings.TrimRight(coreURL, "/")+clustersAPIPath, nil)
383		if err != nil {
384			return "", fmt.Errorf("build clusters request: %w", err)
385		}
386		req.Header.Set("Authorization", "Bearer "+loginJWT)
387		req.Header.Set("Accept", "application/json")
388	
389		resp, err := httpClient.Do(req)
390		if err != nil {
391			return "", fmt.Errorf("list clusters: %w", err)
392		}
393		defer resp.Body.Close()
394		if resp.StatusCode != http.StatusOK {
395			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096)) //nolint:errcheck // best-effort error-detail snippet
396			return "", fmt.Errorf("list clusters: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
397		}
398	
399		var listing struct {
400			Clusters []clusterListingRow `json:"clusters"`
401		}
402		if err := json.NewDecoder(resp.Body).Decode(&listing); err != nil {
403			return "", fmt.Errorf("decode clusters response: %w", err)
404		}
405	
406		var matches []clusterListingRow
407		sawJurisdiction := false
408		for _, row := range listing.Clusters {
409			if row.Jurisdiction != jurisdiction {
410				continue
411			}
412			sawJurisdiction = true
413			if strings.TrimSpace(row.APIURL) != "" {
414				matches = append(matches, row)
415			}
416		}
417		if len(matches) == 0 {
418			if sawJurisdiction {
419				// A cluster row exists for the jurisdiction but carries no apiUrl —
420				// a schema/deploy problem, distinct from "no cell for jurisdiction".
421				return "", fmt.Errorf("cluster for jurisdiction %q advertises no apiUrl (entire-api cell not configured?)", jurisdiction)
422			}
423			return "", fmt.Errorf("no entire-api cell configured for jurisdiction %q", jurisdiction)
424		}
425		chosen := matches[0]
426		for _, row := range matches {
427			if row.IsDefault {
428				chosen = row
429				break
430			}
431		}
432		return strings.TrimRight(chosen.APIURL, "/"), nil
433	}
