435	func exchangeJurisdictionToken(ctx context.Context, coreURL, loginJWT, audience string, httpClient *http.Client) (string, error) {
436		if coreURL == "" {
437			return "", errors.New("no entire-core URL configured for jurisdiction token exchange")
438		}
439		form := httputil.TokenExchangeForm(loginJWT, audience, JurisdictionIdentityScope)
440	
441		token, _, err := httputil.PostOAuthToken(ctx, httpClient, coreURL, form)
442		if err != nil {
443			return "", fmt.Errorf("post token exchange: %w", err)
444		}
445		if strings.TrimSpace(token) == "" {
446			return "", errors.New("token exchange returned an empty access token")
447		}
448		return token, nil
449	}
