15	// agentHelpAnnotation marks an otherwise-hidden command as worth advertising to
16	// coding agents through `entire agent-help`. Hidden commands (e.g. trail) opt in
17	// by setting Annotations[agentHelpAnnotation] = "true".
18	const agentHelpAnnotation = "entire_agent_help"
19	
20	// agentHelpRequiresTrailsAnnotation marks a command whose surface should only be
21	// advertised to agents when trails are enabled for the repo. While the trails
22	// product may not be available to a user yet, agent-help must not point agents at
23	// commands they can't use — so trail-gated commands are hidden until the same
24	// "is trails enabled" signal the first-turn injection already gates on says yes.
25	const agentHelpRequiresTrailsAnnotation = "entire_agent_help_requires_trails"
26	
27	// agentHelpAnnotationEnabled is the truthy value for the agent-help annotations.
28	const agentHelpAnnotationEnabled = "true"
29	
30	// agentHelpOverview is the only hand-maintained prose in agent-help: a terse,
31	// high-level "what entire is for" plus the standing repo-inference rule. It names
32	// no flags or subcommands — those are rendered live from the installed command
33	// tree — so it changes only when a whole capability area lands, not when a flag
34	// is added.
35	const agentHelpOverview = `Entire's CLI is the source of truth for its own usage. Do not guess flags or
36	subcommands — read them from this command. You are already inside the repo:
37	entire auto-detects it from the git origin remote, so never ask the user for the
38	repo name. Pass --repo only to target a DIFFERENT repo.`
39	
40	// newAgentHelpCmd builds the `entire agent-help` command. It is visible in
41	// `entire help` (so agents on transports without context injection can still
42	// find it) and renders agent-facing usage live from rootCmd's command tree.
43	func newAgentHelpCmd(rootCmd *cobra.Command) *cobra.Command {
44		var asJSON bool
45		cmd := &cobra.Command{
46			Use:   "agent-help [command...]",
47			Short: "Machine-readable usage for coding agents (always matches the installed CLI)",
48			Long: `Prints agent-facing usage for the Entire CLI, generated live from the installed
49	command tree so it always matches this binary. With no arguments it prints a
50	high-level map of when to use entire and which subcommand; pass a command path
51	(e.g. "agent-help checkpoint") to see that command's exact, current flags.`,
52			RunE: func(c *cobra.Command, args []string) error {
53				// Resolve the origin remote once and derive both the repo line and the
54				// trails-enablement check from it (avoids two git subprocesses per run).
55				repoLine, trailsEnabled := agentHelpRepoContext(c.Context())
56				out, err := runAgentHelp(rootCmd, args, repoLine, asJSON, trailsEnabled)
57				if err != nil {
58					return err
59				}
60				fmt.Fprint(c.OutOrStdout(), out)
61				return nil
62			},
63		}
64		cmd.Flags().BoolVar(&asJSON, "json", false, "Emit structured JSON instead of text")
65		return cmd
66	}
