68	// agentHelpRepoContext resolves the origin remote ONCE and derives both the repo
69	// line (forge/owner/repo, or "" when it can't be determined — no origin /
70	// detached HEAD — so the renderer degrades gracefully) and whether trails are
71	// enabled for that scope. Previously the repo line and the trails check resolved
72	// origin independently, costing two git subprocesses per `entire agent-help` run.
73	func agentHelpRepoContext(ctx context.Context) (repoLine string, trailsEnabled bool) {
74		scope, err := currentTrailEnablementScope(ctx)
75		if err != nil {
76			return "", false
77		}
78		if scope.Forge != "" && scope.Owner != "" && scope.Repo != "" {
79			repoLine = scope.RepoKey
80		}
81		return repoLine, cachedTrailsEnablementForScope(ctx, scope, time.Now()) == trailEnablementCacheEnabled
82	}
