84	// runAgentHelp resolves args to a command node and renders it. It is pure (no
85	// git / IO): the caller passes the already-resolved repoLine and trailsEnabled.
86	func runAgentHelp(rootCmd *cobra.Command, args []string, repoLine string, asJSON, trailsEnabled bool) (string, error) {
87		target := rootCmd
88		for _, name := range args {
89			child := agentHelpFindChild(target, name)
90			if child == nil {
91				return "", fmt.Errorf("unknown command %q; run `entire agent-help` for the list of commands", name)
92			}
93			// Keep the specific, actionable message for the trail-gated case.
94			if !trailsEnabled && child.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
95				return "", fmt.Errorf("`%s` is unavailable: trails are not enabled for this repo", child.Name())
96			}
97			// The drillable surface must match the advertised surface: a name an agent
98			// guesses for a command the listing intentionally hides (help, deprecated,
99			// or plain-hidden infra like `hooks`) reads as nonexistent here too.
100			if !isAgentHelpAdvertised(child, trailsEnabled) {
101				return "", fmt.Errorf("unknown command %q; run `entire agent-help` for the list of commands", name)
102			}
103			target = child
104		}
105		if asJSON {
106			return renderAgentHelpJSON(rootCmd, target, repoLine, trailsEnabled)
107		}
108		if target == rootCmd {
109			return renderAgentHelpTop(rootCmd, repoLine, trailsEnabled), nil
110		}
111		return renderAgentHelpCommand(target, repoLine, trailsEnabled), nil
112	}
