114	// agentHelpFindChild finds a direct child of parent by name or alias. It
115	// includes hidden commands so an annotated one like trail resolves; the caller
116	// (runAgentHelp) then enforces isAgentHelpAdvertised, so the drillable surface
117	// matches the advertised one.
118	func agentHelpFindChild(parent *cobra.Command, name string) *cobra.Command {
119		for _, sub := range parent.Commands() {
120			if sub.Name() == name {
121				return sub
122			}
123			for _, alias := range sub.Aliases {
124				if alias == name {
125					return sub
126				}
127			}
128		}
129		return nil
130	}
