154	// renderAgentHelpJSON renders the structured form of a command node.
155	func renderAgentHelpJSON(rootCmd, target *cobra.Command, repoLine string, trailsEnabled bool) (string, error) {
156		doc := agentHelpJSON{
157			Command: target.CommandPath(),
158			Short:   target.Short,
159			Long:    strings.TrimSpace(target.Long),
160			Repo:    repoLine,
161		}
162		if target != rootCmd {
163			collect := func(fs *flag.FlagSet) {
164				fs.VisitAll(func(f *flag.Flag) {
165					if f.Hidden {
166						return
167					}
168					doc.Flags = append(doc.Flags, agentHelpFlagJSON{
169						Name:      f.Name,
170						Shorthand: f.Shorthand,
171						Type:      f.Value.Type(),
172						Default:   f.DefValue,
173						Usage:     f.Usage,
174					})
175				})
176			}
177			collect(target.LocalFlags())
178			collect(target.InheritedFlags())
179		}
180		for _, sub := range agentHelpCommands(target, trailsEnabled) {
181			doc.Subcommands = append(doc.Subcommands, agentHelpSubcommandJSON{Name: sub.Name(), Short: sub.Short})
182		}
183		b, err := json.MarshalIndent(doc, "", "  ")
184		if err != nil {
185			return "", fmt.Errorf("marshal agent-help json: %w", err)
186		}
187		return string(b) + "\n", nil
188	}
