191	// agent-help. The listing AND the drill-down resolver share this predicate so
192	// the drillable surface always matches the advertised surface: visible commands
193	// plus hidden commands that opt in via agentHelpAnnotation, minus the help
194	// command, deprecated commands, and (when trails are disabled) trail-gated ones.
195	func isAgentHelpAdvertised(sub *cobra.Command, trailsEnabled bool) bool {
196		if sub.Name() == "help" || sub.Name() == "agent-help" || sub.Deprecated != "" {
197			return false
198		}
199		if sub.Hidden && sub.Annotations[agentHelpAnnotation] != agentHelpAnnotationEnabled {
200			return false
201		}
202		if !trailsEnabled && sub.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
203			return false
204		}
205		return true
