219	// agentHelpRepoBlock formats the auto-detected repo line, degrading gracefully
220	// when the repo can't be resolved (no origin / detached HEAD) rather than
221	// implying a repo that isn't there.
222	func agentHelpRepoBlock(repoLine string) string {
223		// Defense-in-depth: this line is emitted as plain text into agent context and
224		// the user's terminal. A crafted origin URL's control characters (newline,
225		// ANSI escapes) are rejected upstream in gitremote, but never let one reach
226		// this plain-text sink — degrade to the not-detectable message instead.
227		if strings.TrimSpace(repoLine) == "" || strings.IndexFunc(repoLine, unicode.IsControl) >= 0 {
228			return "Current repo: not auto-detectable here (no origin remote / detached HEAD); pass --repo explicitly.\n"
229		}
230		return "Current repo: " + repoLine + "  (auto-detected from origin; pass --repo only for a DIFFERENT repo)\n"
231	}
232	
233	// renderAgentHelpCommand renders one resolved command node for an agent: its
234	// path + Short, its Long description, the auto-detected repo line, its live flag
235	// usages (hidden flags are skipped by cobra), and its advertised subcommands.
236	func renderAgentHelpCommand(cmd *cobra.Command, repoLine string, trailsEnabled bool) string {
237		var b strings.Builder
238		fmt.Fprintf(&b, "%s — %s\n", cmd.CommandPath(), cmd.Short)
239		if long := strings.TrimSpace(cmd.Long); long != "" && long != strings.TrimSpace(cmd.Short) {
240			b.WriteString(long)
241			b.WriteString("\n")
242		}
243		b.WriteString("\n")
244		b.WriteString(agentHelpRepoBlock(repoLine))
245	
246		// LocalFlags()/InheritedFlags() trigger cobra's persistent-flag merge (plain
247		// Flags() does not without Execute) and skip hidden flags in FlagUsages.
248		if usages := strings.TrimRight(cmd.LocalFlags().FlagUsages(), "\n"); usages != "" {
249			b.WriteString("\nFlags:\n")
250			b.WriteString(usages)
251			b.WriteString("\n")
252		}
253		if usages := strings.TrimRight(cmd.InheritedFlags().FlagUsages(), "\n"); usages != "" {
254			b.WriteString("\nInherited flags:\n")
255			b.WriteString(usages)
256			b.WriteString("\n")
257		}
258	
259		if subs := agentHelpCommands(cmd, trailsEnabled); len(subs) > 0 {
260			names := make([]string, 0, len(subs))
261			for _, sub := range subs {
262				names = append(names, sub.Name())
263			}
264			fmt.Fprintf(&b, "\nSubcommands: %s\n", strings.Join(names, " · "))
265			fmt.Fprintf(&b, "Next:  entire agent-help %s <subcommand>\n", strings.TrimPrefix(cmd.CommandPath(), cmd.Root().Name()+" "))
266		}
267		return b.String()
268	}
269	
270	// renderAgentHelpTop renders the top-level agent-facing overview: the curated
271	// intro + rule, the auto-detected repo line, and a live map of the advertised
272	// commands (their Short help), ending with the drill-down pointer.
273	func renderAgentHelpTop(rootCmd *cobra.Command, repoLine string, trailsEnabled bool) string {
274		var b strings.Builder
275		b.WriteString(agentHelpOverview)
276		b.WriteString("\n\n")
277		b.WriteString(agentHelpRepoBlock(repoLine))
278		b.WriteString("\nWhen to use entire:\n")
279		for _, sub := range agentHelpCommands(rootCmd, trailsEnabled) {
280			fmt.Fprintf(&b, "  %-12s %s\n", sub.Name(), sub.Short)
281		}
282		// Use an example command that is actually advertised here (trail is gated on
283		// trails being enabled), so we never point at a command the agent can't use.
284		example := "checkpoint"
285		if trailsEnabled {
286			example = "trail"
287		}
288		fmt.Fprintf(&b, "\nDrill in for exact, currently-installed flags:  entire agent-help <command>  (e.g. entire agent-help %s)\n", example)
289		b.WriteString("Add --json for structured output.\n")
290		return b.String()
291	}
